import{f as u}from"./chunk-H4IOZYCN.js";import{Ga as c,Sa as h,Ta as i,Ua as o,Va as g,gb as p,jb as s,kb as n,ob as m,sa as t}from"./chunk-GQZEEOY3.js";var f=e=>["/projects",e],j=(()=>{class e{static{this.\u0275fac=function(r){return new(r||e)}}static{this.\u0275cmp=c({type:e,selectors:[["app-project-card"]],inputs:{project:"project"},decls:9,vars:8,consts:[[1,"project-card",3,"routerLink"],[1,"thumb"],[1,"info"],[1,"category"],[1,"title"],[1,"location"]],template:function(r,a){r&1&&(i(0,"a",0),g(1,"div",1),i(2,"div",2)(3,"p",3),s(4),o(),i(5,"h3",4),s(6),o(),i(7,"p",5),s(8),o()()()),r&2&&(h("routerLink",m(6,f,a.project.slug)),t(),p("background-image","url("+a.project.heroImage+")"),t(3),n(a.project.categories.join(" / ")),t(2),n(a.project.title),t(2),n(a.project.location))},dependencies:[u],styles:[".project-card[_ngcontent-%COMP%]{display:block;position:relative;overflow:hidden;aspect-ratio:4/5;background:#f1f1f1}.thumb[_ngcontent-%COMP%]{position:absolute;inset:0;background-size:cover;background-position:center;transition:transform .5s ease}.project-card[_ngcontent-%COMP%]:hover   .thumb[_ngcontent-%COMP%]{transform:scale(1.06)}.info[_ngcontent-%COMP%]{position:absolute;left:0;right:0;bottom:0;padding:24px;background:linear-gradient(180deg,transparent 0%,rgba(0,0,0,.75) 100%);color:#fff}.category[_ngcontent-%COMP%]{font-family:Montserrat,sans-serif!important;font-size:11px!important;line-height:16px!important;text-transform:uppercase;letter-spacing:.1em;margin-bottom:6px!important;color:#fff!important}.title[_ngcontent-%COMP%]{font-family:Montserrat,sans-serif!important;font-weight:400!important;font-size:18px!important;line-height:24px!important;text-align:left!important;color:#fff!important;margin:0 0 4px!important}.location[_ngcontent-%COMP%]{font-family:Montserrat,sans-serif!important;font-weight:300!important;font-size:13px!important;line-height:18px!important;color:#fff!important;opacity:.85;margin:0!important}"],changeDetection:0})}}return e})();var d=[{slug:"gajlakshmi",title:"Gajlakshmi",categories:["architecture","interior"],location:"Gujar Mala, Shirur, Pune",area:"4,200 sq.ft. built-up",year:2023,heroImage:"assets/projects/gajlakshmi/entrance-1.jpg",galleryImages:["assets/projects/gajlakshmi/entrance-1.jpg","assets/projects/gajlakshmi/living-room-1.jpg","assets/projects/gajlakshmi/family-room-1.jpg","assets/projects/gajlakshmi/devghar-1.jpg","assets/projects/gajlakshmi/master-bedroom-1.jpg","assets/projects/gajlakshmi/guest-bedroom-1.jpg","assets/projects/gajlakshmi/bedroom-balcony-1.jpg","assets/projects/gajlakshmi/office-1.jpg"],summary:"A 4,200 sq.ft. residential bungalow in Shirur blending modern minimalism with traditional Maharashtrian warmth.",description:["Gajlakshmi is a 4,200 sq.ft. residential bungalow on a 4,000 sq.ft. plot in Gujar Mala, Shirur, completed in 2023 after a 16-month build. The design blends modern minimalism with traditional Maharashtrian warmth \u2014 natural materials, contrasting textures, and carefully considered detailing run through every room.","Golden teak veneer, jet-black Italian marble, and carved black basalt stone set the material palette at the entrance, carrying through to a living room anchored by a marble-and-veneer TV unit, a Devghar crafted from polished wood and translucent acrylic, and bedrooms styled with warm wood panelling and neutral, tactile fabrics."],specs:[{label:"Location",value:"Gujar Mala, Shirur, Pune - 412210"},{label:"Plot Area",value:"4,000 sq.ft."},{label:"Built-up Area",value:"4,200 sq.ft."},{label:"Completion",value:"2023 (16-month build)"},{label:"Principal Architect",value:"Ar. Pooja Chaudhari"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"Hafele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Kitchen Counters",value:"Kalinga Stone"},{label:"Lighting",value:"Hybec"}],sections:[{heading:"Entrance",body:["A grand house entrance that exudes opulence and charm: sleek, jet-black marble flooring gleams under the soft, warm light of a beautifully crafted wooden ceiling, while walls wrapped in golden teak veneer bring a touch of timeless elegance to the arrival experience.","The front door combines the warmth of wood with the sleekness of black basalt stone. Evenly spaced vertical wood slats frame a door face carved into a repeating geometric pattern of three-dimensional stars."],image:"assets/projects/gajlakshmi/entrance-1.jpg"},{heading:"Living Room",body:["Step into an impeccably designed living room where the TV unit is the crowning jewel \u2014 its Italian marble top glistens in perfect harmony with exquisite wood veneer, while a touch of white deco paint adds a contemporary edge that marries tradition and modernity.","Plush grey sofas offer a comfortable, inviting contrast to the richness of the surrounding wood."],image:"assets/projects/gajlakshmi/living-room-1.jpg"},{heading:"Family Room",body:["An Indian-style seating arrangement forms the focal point of the family room, blending effortlessly with the space\u2019s overall design. Intricate wooden carvings across the backrest and handrest bring traditional craftsmanship into an otherwise contemporary room."],image:"assets/projects/gajlakshmi/family-room-1.jpg"},{heading:"Devghar",body:["The Devghar is a masterpiece of craftsmanship \u2014 a sanctuary of spiritual reflection fashioned from a harmonious blend of rich, polished wood and translucent acrylic. The wood\u2019s warm, earthy tones lend a sense of natural connection and grounding.","Intricate carvings with small copper bells hang throughout, designed to jingle softly when the doors open, while gentle lighting completes a calming atmosphere fit for a place of worship."],image:"assets/projects/gajlakshmi/devghar-1.jpg"},{heading:"Master Bedroom",body:["The master bedroom pairs warm wooden accents with modern minimalism. A wardrobe with vertical wood-and-white panelling creates a sleek, functional aesthetic, while light grey wall panelling adds subtle sophistication.","A custom headboard with tropical-inspired artwork introduces a vibrant, artistic focal point, balanced by soft, neutral tones and cozy bed styling with pops of teal and mustard."],image:"assets/projects/gajlakshmi/master-bedroom-1.jpg"},{heading:"Master Bedroom Toilet",body:["A modern, minimalist bathroom defined by clean lines and polished surfaces. Warm wood tones, cool white ceramic, and contrasting black tiles come together for a visually appealing, sophisticated space."],image:"assets/projects/gajlakshmi/master-bedroom-toilet-1.jpg"},{heading:"Guest Bedroom",body:["The guest bedroom is a masterful display of design, artfully employing a captivating neutral colour scheme that exudes timeless elegance."],image:"assets/projects/gajlakshmi/guest-bedroom-1.jpg"},{heading:"Bedroom Balcony",body:["The bedroom balcony is a haven of tranquility and aesthetics. Light-toned wall textures exude a delicate charm, lending a rustic touch that sets the tone for relaxation.","The bed is framed by gleaming grooves that provide a captivating accent, paired with a sleek, minimalist side table and contemporary suspended light fixtures that infuse modernity with an air of grace."],image:"assets/projects/gajlakshmi/bedroom-balcony-1.jpg"},{heading:"Office",body:["The home office pairs warm wood with crisp white surfaces for a workspace that feels both professional and personal. Its centrepiece is a sculpted executive desk, a single sweep of wood veneer that curves down to the floor, topped with frosted glass and edged in white, paired with a tan leather executive chair.","Behind the desk, a wood-framed open grid shelf displays golden sculptures and accents against a dark backdrop. A long, low wooden credenza runs beneath a large portrait panel, while vertical wood slats and a textured grey wall add depth. Track spotlights, recessed downlights and glossy white marble flooring keep the space bright, with grey seating for visitors completing the room."],image:"assets/projects/gajlakshmi/office-1.jpg"}]},{slug:"chandradev",title:"Chandradev",categories:["interior"],location:"Parner, Nagar",area:"1,895 sq.ft.",year:2025,heroImage:"assets/projects/chandradev/entrance-foyer-1.jpg",galleryImages:["assets/projects/chandradev/entrance-foyer-1.jpg","assets/projects/chandradev/living-room-1.jpg","assets/projects/chandradev/kitchen-1.jpg","assets/projects/chandradev/puja-room-1.jpg","assets/projects/chandradev/bedroom-1-1.jpg","assets/projects/chandradev/bedroom-2-1.jpg","assets/projects/chandradev/bedroom-3-1.jpg"],summary:"A 1,895 sq.ft. apartment interior in Parner following a Modern Japandi-European Fusion design language.",description:["Chandradev is a 1,895 sq.ft. apartment interior in Parner, completed in 2025 over a year-long build, following a Modern Japandi-European Fusion design language inspired by Japandi design principles.","Balancing functionality, natural light, ventilation, and Vastu principles shaped the design through several iterations. The greater challenge was creating a sense of volume and spaciousness within the constraints of a flat \u2014 achieved through careful planning, material choices, and a considered play of light and levels, so every corner feels open, bright, and connected."],specs:[{label:"Location",value:"Parner, Nagar"},{label:"Built-up Area",value:"1,895 sq.ft."},{label:"Completion",value:"2025 (1-year build)"},{label:"Principal Architect",value:"Ar. Pooja Akash Chaudhari"},{label:"Design Style",value:"Modern Japandi-European Fusion"},{label:"Flooring",value:"Italian Marble"},{label:"Wall Cladding",value:"Green MDF, Deco Wood Veneer, Mikasa Ply"},{label:"Kitchen",value:"Nano White Top, Hytich Modular Kitchen"},{label:"Furniture",value:"Mikasa Ply, Green Ply MDF, Deco Veneer"},{label:"Sanitary Ware",value:"Grohe"},{label:"Windows",value:"UPVC (Simta)"},{label:"Lighting",value:"Hybec"},{label:"Paint",value:"Asian Paints"}],sections:[{heading:"Entrance Foyer",tagline:"Divine Abode",body:["Italian marble flooring and veneered wood cladding set a warm, textured tone at the entry, anchored by a matte-wood console with a brushed-gold accent piece beneath a statement antique-brass pendant light.","A gold-trimmed mirror and recessed cove lighting open up the narrow foyer, making for a quiet, grounded welcome into the home."],image:"assets/projects/chandradev/entrance-foyer-1.jpg",gallery:["assets/projects/chandradev/entrance-foyer-2.jpg"]},{heading:"Living Room",tagline:"Timeless Harmony",body:["The living room centres on the TV unit \u2014 the one design element the team holds closest from the entire project \u2014 framed by beige Italian marble flooring with brass inlay borders and a statement brushed-gold chandelier overhead.","A carved wooden jali partition door doubles as a sculptural screen between the living and kitchen zones."],image:"assets/projects/chandradev/living-room-1.jpg",gallery:["assets/projects/chandradev/living-room-2.jpg","assets/projects/chandradev/living-room-3.jpg"]},{heading:"Kitchen",tagline:"Nourishing Hearth",body:["A matte sage-green modular kitchen with nano white quartz countertops opens onto a breakfast island and bar seating \u2014 the home\u2019s everyday gathering point, lit by pendant lighting and concealed under-cabinet LEDs."],image:"assets/projects/chandradev/kitchen-1.jpg",gallery:["assets/projects/chandradev/kitchen-2.jpg","assets/projects/chandradev/kitchen-3.jpg"]},{heading:"Puja Room",tagline:"Traditional Serenity",body:["A sacred retreat framed by an arched, temple-inspired wooden doorway. The idol sits on a raised platform dressed in red cloth and flanked by brass diyas, with rich wood panelling and white walls keeping the sanctum calm and uncluttered."],image:"assets/projects/chandradev/puja-room-1.jpg"},{heading:"Bedroom 1",tagline:"Serenity",body:["A blush-pink retreat built around a tall, tufted velvet headboard with matching floor-to-ceiling wall panelling and curtains. A floating wood-and-pink study nook and glass balcony doors round out a room designed for warmth and calm."],image:"assets/projects/chandradev/bedroom-1-1.jpg",gallery:["assets/projects/chandradev/bedroom-1-2.jpg","assets/projects/chandradev/bedroom-1-3.jpg"]},{heading:"Bedroom 2",tagline:"Tranquil",body:["A sage-green and warm-wood bedroom anchored by a textured upholstered headboard and a handle-less wardrobe wall finished in muted green with white accents. A built-in study nook continues the same palette into a complete work-and-rest setup."],image:"assets/projects/chandradev/bedroom-2-1.jpg",gallery:["assets/projects/chandradev/bedroom-2-2.jpg","assets/projects/chandradev/bedroom-2-3.jpg"]},{heading:"Bedroom 3",body:["A geometric textured accent wall anchors the bed, paired with a curved white panel and a grey upholstered headboard styled with striped linens and gold-cream bolsters.","Opposite, a vertically striped wardrobe in beige, white, and wood elongates the room while tying back to the polished stone flooring."],image:"assets/projects/chandradev/bedroom-3-1.jpg",gallery:["assets/projects/chandradev/bedroom-3-2.jpg","assets/projects/chandradev/bedroom-3-3.jpg"]}],photographer:"Ar. Aroh Thombre"},{slug:"shreenivas",title:"Shreenivas",categories:["interior"],location:"",area:"",heroImage:"assets/projects/shreenivas/entrance-1.jpg",galleryImages:["assets/projects/shreenivas/entrance-1.jpg","assets/projects/shreenivas/entrance-lobby-1.jpg","assets/projects/shreenivas/living-room-1.jpg","assets/projects/shreenivas/dining-1.jpg","assets/projects/shreenivas/kitchen-1.jpg","assets/projects/shreenivas/master-bedroom-1.jpg","assets/projects/shreenivas/master-bedroom-toilet-1.jpg","assets/projects/shreenivas/daughters-bedroom-1.jpg","assets/projects/shreenivas/sons-bedroom-1.jpg"],summary:"A veneer-rich residential interior defined by deco detailing, a tropical mural entrance, and individually themed bedrooms.",description:["Shreenivas is a residential interior fit-out built around a warm, veneer-forward material palette and deco detailing, from a tropical mural entrance and a marble-finished TV unit in the living room to a sculptural, bubble-textured hidden door dividing the dining space.","Each bedroom carries its own distinct character \u2014 a deco-and-veneer master suite, a green-and-grey daughter's room, and individually themed spaces throughout \u2014 tied together by rich wood tones, fluted glass, and considered lighting."],specs:[{label:"Principal Architect",value:"Ar. Pooja Chaudhari"}],sections:[{heading:"Entrance",body:["A stunning tropical mural sets a vivid, exotic tone at the entrance, paired with sophisticated veneer wall cladding for warmth and texture \u2014 a captivating, art-forward welcome into the home."],image:"assets/projects/shreenivas/entrance-1.jpg",gallery:["assets/projects/shreenivas/entrance-2.jpg","assets/projects/shreenivas/entrance-3.jpg"]},{heading:"Entrance Lobby",body:["A sleek veneer finish carries the entrance's refined luxury through into the lobby, its rich texture and polished craftsmanship setting a sophisticated tone that resonates through the rest of the home."],image:"assets/projects/shreenivas/entrance-lobby-1.jpg",gallery:["assets/projects/shreenivas/entrance-lobby-2.jpg","assets/projects/shreenivas/entrance-lobby-3.jpg"]},{heading:"Living Room",body:["Deco influences meet luxurious veneer accents for a mood of refined comfort, with wooden window frames set with fluted glass panels adding texture and light. A marble-finished TV unit anchors the room, blending classic and contemporary design in equal measure."],image:"assets/projects/shreenivas/living-room-1.jpg",gallery:["assets/projects/shreenivas/living-room-2.jpg"]},{heading:"Dining Area",body:["A hidden door, textured with a bubble-sphere pattern, doubles as both a functional partition and a sculptural piece of art \u2014 a quietly striking focal point for the dining space."],image:"assets/projects/shreenivas/dining-1.jpg",gallery:["assets/projects/shreenivas/dining-2.jpg"]},{heading:"Kitchen",body:["A chic breakfast counter and sleek glass-profile shutters define the kitchen, which flows seamlessly into a tranquil, veneer-clad puja room \u2014 a considered transition from everyday function to a calmer, spiritual corner of the home."],image:"assets/projects/shreenivas/kitchen-1.jpg",gallery:["assets/projects/shreenivas/kitchen-2.jpg","assets/projects/shreenivas/kitchen-3.jpg"]},{heading:"Master Bedroom",body:["Deco detailing and rich veneer finishes give the master bedroom a luxurious, layered character, blending classic and contemporary styling into a warm, indulgent retreat."],image:"assets/projects/shreenivas/master-bedroom-1.jpg",gallery:["assets/projects/shreenivas/master-bedroom-2.jpg"]},{heading:"Master Bedroom Toilet",body:["Louvered veneer panelling and a sleek glass partition bring warmth and structure to the ensuite, balancing rich timber texture against light, airy glazing for a calm, contemporary finish."],image:"assets/projects/shreenivas/master-bedroom-toilet-1.jpg",gallery:["assets/projects/shreenivas/master-bedroom-toilet-2.jpg"]},{heading:"Daughter's Bedroom",body:["A soft palette of green, white, and grey gives the daughter's bedroom a calm, tailored character \u2014 a thoughtfully curated retreat that balances comfort with personality."],image:"assets/projects/shreenivas/daughters-bedroom-1.jpg",gallery:["assets/projects/shreenivas/daughters-bedroom-2.jpg"]},{heading:"Son's Bedroom",body:[],image:"assets/projects/shreenivas/sons-bedroom-1.jpg",gallery:["assets/projects/shreenivas/sons-bedroom-2.jpg","assets/projects/shreenivas/sons-bedroom-3.jpg"]}]},{slug:"cultural-contours-modern-minimalisms",title:"Cultural Contours & Modern Minimalisms",categories:["architecture","interior"],location:"",area:"",heroImage:"assets/projects/cultural-contours-modern-minimalisms/dining-space-1.jpg",galleryImages:["assets/projects/cultural-contours-modern-minimalisms/dining-space-1.jpg","assets/projects/cultural-contours-modern-minimalisms/living-room-1.jpg","assets/projects/cultural-contours-modern-minimalisms/bedroom-1.jpg","assets/projects/cultural-contours-modern-minimalisms/reception-1.jpg","assets/projects/cultural-contours-modern-minimalisms/consultation-office-1.jpg","assets/projects/cultural-contours-modern-minimalisms/treatment-area-1.jpg"],summary:"A home and a dental clinic under one roof, joined by a shared language of polished stone and refined woodwork.",description:["Cultural Contours & Modern Minimalisms answers an unusual brief: a fluid transition between a vibrant, culturally rooted home and a highly professional, clinical office. The design team achieved this by establishing a shared material language \u2014 polished stone flooring and refined woodwork \u2014 while letting each zone express its purpose through colour, form and texture.","The residential quarters reimagine traditional motifs with a contemporary edge, from a floral block-print screen hung with brass bells to an indigo arched niche carrying a golden tree-of-life. Beyond it, the Shree Dental suite shifts to tranquility and hygiene, with vertical light-oak panelling, a sculptural marble-textured reception desk and calm, ergonomic consultation spaces."],specs:[{label:"Location",value:""},{label:"Plot Area",value:""},{label:"Built-up Area",value:""},{label:"Completion",value:""},{label:"Principal Architect",value:""},{label:"Flooring",value:"Polished grey marble"},{label:"Wall Cladding",value:""},{label:"Doors & Partitions",value:"Deep walnut and light oak veneers"},{label:"Furniture Fittings",value:""},{label:"Upholstery",value:"Custom teal upholstery"},{label:"Sanitary Ware",value:""},{label:"Windows",value:""},{label:"Kitchen Counters",value:""},{label:"Lighting",value:""},{label:"Artisanal Elements",value:"Pichwai and block-printed textile panels, custom brass bells, laser-cut metallic wall art"}],sections:[{heading:"Living Room",body:["A vibrant teal sofa provides a striking focal point against a neutral backdrop, balanced by an exquisite wooden room divider.","The divider integrates a traditional floral block-print screen and suspended brass bells, creating an experiential entry point that plays on light, shadow and soft acoustics."],image:"assets/projects/cultural-contours-modern-minimalisms/living-room-1.jpg"},{heading:"Dining Space",body:["Dominated by a deep indigo arched niche, the dining area features an intricate golden tree-of-life motif. Flanked by sleek, modern grey dining chairs and rich wood panelling, it balances regal craftsmanship with clean-lined sophistication.","A traditional wooden swing (jhoola) nearby completes the warm, family-oriented ambiance."],image:"assets/projects/cultural-contours-modern-minimalisms/dining-space-1.jpg",gallery:["assets/projects/cultural-contours-modern-minimalisms/dining-space-2.jpg"]},{heading:"Bedroom",body:[],image:"assets/projects/cultural-contours-modern-minimalisms/bedroom-1.jpg"},{heading:"Reception",body:["The clinic greets visitors with a soothing palette of vertical light-oak wall panelling.","The reception desk introduces a sculptural element with a curved, marble-textured front piece, immediately establishing a premium yet welcoming atmosphere."],image:"assets/projects/cultural-contours-modern-minimalisms/reception-1.jpg"},{heading:"Consultation Office",body:["Prioritising spatial efficiency and comfort, the doctor\u2019s room features custom light-oak cabinetry, minimalist floating shelves, and wide windows that flood the room with natural light.","An integrated wooden ceiling drop anchors the main desk area, reflecting the clinic\u2019s focus on structured, calming and clean ergonomics."],image:"assets/projects/cultural-contours-modern-minimalisms/consultation-office-1.jpg"},{heading:"Treatment Area",body:[],image:"assets/projects/cultural-contours-modern-minimalisms/treatment-area-1.jpg",gallery:["assets/projects/cultural-contours-modern-minimalisms/treatment-area-2.jpg"]}]},{slug:"evolving-fitness-through-industrial-sophistication",title:"Evolving Fitness through Industrial Sophistication",categories:["interior"],location:"",area:"",heroImage:"assets/projects/evolving-fitness-through-industrial-sophistication/turf-strip-1.jpg",galleryImages:["assets/projects/evolving-fitness-through-industrial-sophistication/reception-lobby-1.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/conference-room-1.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/main-gym-floor-1.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/turf-strip-1.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/group-activity-hall-1.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/yoga-mat-studio-1.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/locker-changing-area-1.jpg"],summary:"Dumbbell Bee: a large fitness facility where heavy lifting, group cardio, consultations and administration share one industrial-chic roof.",description:["The layout for Dumbbell Bee focuses on user psychology, zoning, and spatial optimisation. The design team was tasked with creating a massive fitness facility that feels unified yet functionally segmented, ensuring that active heavy lifting, group cardio, private consultations, and administration coexist smoothly under one roof.","The brand\u2019s signature yellow runs through lockers, graphics and entrance lighting. Engineered wood planks warm the corporate zones, impact-absorbing rubber and synthetic turf take the training floor, and the lighting moves from cool recessed spotlights in active zones to warm mirror backlighting and focused industrial track lamps."],specs:[{label:"Location",value:""},{label:"Plot Area",value:""},{label:"Built-up Area",value:""},{label:"Completion",value:""},{label:"Principal Architect",value:""},{label:"Flooring",value:"Engineered wood planks (corporate zones), non-slip tiles (common pathways), impact-absorbing rubber mats (free weights), high-density synthetic turf (functional tracks)"},{label:"Wall Cladding",value:""},{label:"Doors & Partitions",value:"Acoustic glass partitions"},{label:"Furniture Fittings",value:""},{label:"Sanitary Ware",value:""},{label:"Windows",value:""},{label:"Lighting",value:"Cool recessed spotlights, warm LED mirror backlighting, industrial track lamps"},{label:"Branding",value:"Signature yellow across lockers, graphics and entrance lighting"}],sections:[{heading:"Reception Lobby",tagline:"The Corporate Welcoming",body:["The journey begins at a wide entrance marked by clean typography and backlit signage.","The main counter features a striking, clean marble-textured finish, set against rich, deep wood plank flooring that instantly adds warmth and premium hospitality appeal. Dark grey ribbed ceiling panels overhead mimic industrial textures while concealing technical lighting tracks."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/reception-lobby-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/reception-lobby-2.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/reception-lobby-3.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/reception-lobby-4.jpg"]},{heading:"Conference & Consultation Room",tagline:"The Corporate Welcoming",body:["Separated by a seamless acoustic glass partition, the meeting space maintains visual connectivity while offering complete privacy. It features minimalist modern leather chairs, an expansive oak conference table, and an abundance of natural light through large windows."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/conference-room-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/conference-room-2.jpg"]},{heading:"Main Gym Floor",tagline:"The Main Workout Floor",body:["The core training arena adopts a raw, energetic industrial-chic mood, dominated by exposed concrete-toned walls and open-grid industrial ceilings with suspended track lighting.","The expansive floor plate is structurally organised to accommodate high-end selectorized and plate-loaded strength stations without feeling crowded."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/main-gym-floor-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/main-gym-floor-2.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/main-gym-floor-3.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/main-gym-floor-4.jpg"]},{heading:"Turf Strip",tagline:"The Functionality Strip",body:["A vibrant, lime-green indoor turf runway acts as a visual anchor and a dedicated track for functional drills, sled pushes, and agility work, introducing an instant burst of kinetic energy to the neutral floor."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/turf-strip-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/turf-strip-2.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/turf-strip-3.jpg"]},{heading:"Group Activity Hall",tagline:"Group Activity, Yoga & Utility",body:["A massive, clean-lined hall features a full-length wall mirror illuminated by seamless perimeter LED strip lights. This setup provides perfect posture feedback while visually doubling the room\u2019s footprint for step aerobics, dance, and group classes."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/group-activity-hall-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/group-activity-hall-2.jpg"]},{heading:"Yoga & Mat Studio",tagline:"Group Activity, Yoga & Utility",body:["A more intimate area featuring specialised floor mats, custom wall graphics depicting yoga postures, and soft overhead spotlights designed to induce focus and mindfulness."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/yoga-mat-studio-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/yoga-mat-studio-2.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/yoga-mat-studio-3.jpg"]},{heading:"Locker & Changing Area",tagline:"Group Activity, Yoga & Utility",body:["The sleek utility corridor combines warmth and function, featuring rich wood floors, clean grey walls, and distinct bright yellow lockers that match the corporate brand identity.","A clean dressing area complete with a minimalist bench and privacy curtains provides a highly functional retreat for members post-workout."],image:"assets/projects/evolving-fitness-through-industrial-sophistication/locker-changing-area-1.jpg",gallery:["assets/projects/evolving-fitness-through-industrial-sophistication/locker-changing-area-2.jpg","assets/projects/evolving-fitness-through-industrial-sophistication/locker-changing-area-3.jpg"]}]},{slug:"dcf-office-ahilyanagar",title:"DCF Office, Ahilyanagar",categories:["interior"],location:"Van Vibhag, Ahilyanagar",area:"850 sq.ft. built-up",year:2025,heroImage:"assets/projects/dcf-office-ahilyanagar/officers-cabin-1.jpg",galleryImages:["assets/projects/dcf-office-ahilyanagar/officers-cabin-1.jpg","assets/projects/dcf-office-ahilyanagar/waiting-area-1.jpg","assets/projects/dcf-office-ahilyanagar/officers-cabin-5.jpg","assets/projects/dcf-office-ahilyanagar/officers-cabin-3.jpg"],heroVideo:{loop:{src:"assets/projects/dcf-office-ahilyanagar/video/hero-loop.mp4",poster:"assets/projects/dcf-office-ahilyanagar/video/hero-loop.jpg",orientation:"portrait"},film:{src:"assets/projects/dcf-office-ahilyanagar/video/film.mp4",poster:"assets/projects/dcf-office-ahilyanagar/video/film.jpg",orientation:"portrait",durationSeconds:34}},summary:"A government office for Ahilyanagar\u2019s Deputy Conservator of Forests, pairing warm wood detailing with a crisp, official restraint.",description:["Designed for the Deputy Conservator of Forests\u2019 office in Ahilyanagar, this 850 sq.ft. interior fits an officer\u2019s cabin and an adjoining waiting area into a single composed sequence. Generous teak-toned ceilings, fluted panelling, and a backlit departmental emblem lend the space an official gravity, while softer carpeted flooring and planting keep it approachable.","A warm wood-finish veneer runs across the ceiling and principal furniture for continuity, set against fluted MDF panelling in soft off-white and a gypsum false ceiling. The officer\u2019s desk and open display shelving combine wood grain with ribbed detailing and integrated LED strip lighting, while grey modular carpet tiles, fabric-upholstered wooden chairs, and a mix of recessed spotlights, linear pendants, and concealed LEDs complete a palette that stays professional without feeling austere."],specs:[{label:"Location",value:"Van Vibhag, Ahilyanagar"},{label:"Plot Area",value:""},{label:"Built-up Area",value:"850 sq.ft."},{label:"Completion",value:"2025"},{label:"Principal Architect",value:"Ar. Akash Chaudhari, ID. Pooja Akash Chaudhari"},{label:"Flooring",value:"Grey modular carpet tiles with a subtle linear pattern"},{label:"Wall Cladding",value:"Fluted MDF/WPC panelling in off-white; white matte wall paint"},{label:"Doors & Partitions",value:""},{label:"Furniture Fittings",value:"Wooden furniture in teak finish with fabric upholstery; wood-finish laminate/veneer desk and ceiling; white laminate cabinetry"},{label:"Sanitary Ware",value:""},{label:"Windows",value:"Neutral-toned roller blinds"},{label:"Lighting",value:"Recessed spotlights, linear pendant lights, concealed LED strip lighting (backlit emblem & shelving)"}],sections:[{heading:"Officer\u2019s Cabin",body:["The design depicts a meticulously furnished office belonging to the Deputy Conservator of Forests, Ahilyanagar \u2014 modern and minimalistic, with clean lines and neutral colours throughout.","A large dark-wood executive desk sits centrally, flanked by two identical built-in wooden shelves with multiple compartments, potted plants, and warm integrated LED lighting. Above the desk, a gold departmental emblem representing the forest department is mounted on the wall.","Walls are painted a bright, neutral off-white in contrast to the deep-toned wood furniture, while the ceiling is paneled in rich dark-brown wood. A framed regional map is displayed prominently, and the floor is finished in a grey and light-grey patterned carpet."],image:"assets/projects/dcf-office-ahilyanagar/officers-cabin-1.jpg",gallery:["assets/projects/dcf-office-ahilyanagar/officers-cabin-2.jpg","assets/projects/dcf-office-ahilyanagar/officers-cabin-3.jpg","assets/projects/dcf-office-ahilyanagar/officers-cabin-4.jpg","assets/projects/dcf-office-ahilyanagar/officers-cabin-5.jpg"]},{heading:"Waiting Area",body:["A modern waiting area pairs comfortable grey upholstered seating \u2014 two armchairs and a sofa \u2014 with a wooden side table, a potted plant, and a wall clock, creating a sense of quiet elegance just outside the cabin.","Neutral roller blinds, a muted palette of greys and tans, and bright, even lighting keep the space serene and orderly, echoing the formality of the office beyond."],image:"assets/projects/dcf-office-ahilyanagar/waiting-area-1.jpg"}],reels:[{title:"Officer\u2019s Cabin",src:"assets/projects/dcf-office-ahilyanagar/video/officers-cabin-loop.mp4",poster:"assets/projects/dcf-office-ahilyanagar/video/officers-cabin-loop.jpg",durationSeconds:8},{title:"Waiting Area",src:"assets/projects/dcf-office-ahilyanagar/video/waiting-area-loop.mp4",poster:"assets/projects/dcf-office-ahilyanagar/video/waiting-area-loop.jpg",durationSeconds:5}]},{slug:"mr-sagar-bhagat",title:"Mr. Sagar Bhagat",categories:["interior"],location:"Shikrapur",area:"2000 sq.ft. plot",year:2024,heroImage:"assets/projects/mr-sagar-bhagat/living-room-1.jpg",galleryImages:["assets/projects/mr-sagar-bhagat/living-room-1.jpg","assets/projects/mr-sagar-bhagat/living-room-3.jpg","assets/projects/mr-sagar-bhagat/dining-kitchen-1.jpg","assets/projects/mr-sagar-bhagat/pooja-1.jpg","assets/projects/mr-sagar-bhagat/bedroom-2-1.jpg"],heroVideo:{loop:{src:"assets/projects/mr-sagar-bhagat/video/hero-loop.mp4",poster:"assets/projects/mr-sagar-bhagat/video/hero-loop.jpg",orientation:"portrait"},film:{src:"assets/projects/mr-sagar-bhagat/video/film.mp4",poster:"assets/projects/mr-sagar-bhagat/video/film.jpg",orientation:"portrait",durationSeconds:80}},summary:"A warm contemporary 3BHK residence in Shikrapur, where natural timber ties together the living, dining, pooja and private spaces.",description:["The residence is shaped around a warm, contemporary material language where timber becomes the visual thread connecting the living, dining, pooja and private spaces. Light stone-look flooring and ivory surfaces create an airy base, allowing sculptural 3D textures, crafted timber details and metallic highlights to take centre stage.","Natural walnut and teak-toned veneer runs across the TV wall, doors, paneling and ceiling insets, set against PU-painted ivory cabinetry, muted mauve laminate accents and restrained brushed-brass detailing. A gypsum false ceiling with framed timber insets, concealed warm LED strips and sculptural pendant fittings complete a refined, functional and cohesive interior."],specs:[{label:"Location",value:"Shikrapur"},{label:"Plot Area",value:"2000 sq.ft."},{label:"Built-up Area",value:""},{label:"Completion",value:"2024"},{label:"Principal Architect",value:"Ar. Akash Chaudhari, ID. Pooja Akash Chaudhari"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP, Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"H\xE4fele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Lighting",value:"Hybec"},{label:"Kitchen",value:"Kalinga Stone"},{label:"Hardware",value:"H\xE4fele, Hettich, Chetna, Quba"},{label:"Paint",value:"Asian Paints"},{label:"Construction Materials",value:"Cement (Birla A1), Steel (Polad)"},{label:"Artifacts",value:"IKEA, White House"}],sections:[{heading:"Living Room",body:["The living room introduces a statement floral relief as an art-integrated focal point, set within sculptural 3D textured wall panels and framed by natural timber."],image:"assets/projects/mr-sagar-bhagat/living-room-1.jpg",gallery:["assets/projects/mr-sagar-bhagat/living-room-2.jpg","assets/projects/mr-sagar-bhagat/living-room-3.jpg","assets/projects/mr-sagar-bhagat/living-room-4.jpg"]},{heading:"Dining & Kitchen",body:["The kitchen is part of the open living and dining area, creating a cohesive and sociable atmosphere."],image:"assets/projects/mr-sagar-bhagat/dining-kitchen-1.jpg"},{heading:"Pooja",body:["The pooja space translates traditional craftsmanship through carved timber, jali patterns and brass-toned details."],image:"assets/projects/mr-sagar-bhagat/pooja-1.jpg"},{heading:"Bedroom 1",body:[],image:"assets/projects/mr-sagar-bhagat/bedroom-1-1.jpg"},{heading:"Bedroom 2 & Study",body:["The study shifts into a softer mauve palette, adding a youthful personalised moment."],image:"assets/projects/mr-sagar-bhagat/bedroom-2-1.jpg"}],reels:[{title:"Dining & Kitchen",src:"assets/projects/mr-sagar-bhagat/video/kitchen-loop.mp4",poster:"assets/projects/mr-sagar-bhagat/video/kitchen-loop.jpg",durationSeconds:5},{title:"Bedroom 1",src:"assets/projects/mr-sagar-bhagat/video/bedroom-1-loop.mp4",poster:"assets/projects/mr-sagar-bhagat/video/bedroom-1-loop.jpg",durationSeconds:7},{title:"Bedroom 2 & Study",src:"assets/projects/mr-sagar-bhagat/video/bedroom-2-loop.mp4",poster:"assets/projects/mr-sagar-bhagat/video/bedroom-2-loop.jpg",durationSeconds:8}],photographer:"@manthanyadav.studio"},{slug:"mr-vaibhav-dhokle",title:"Mr. Vaibhav Dhokle",categories:["architecture","interior"],location:"Karandi",area:"3,000 sq.ft. built-up",year:2025,heroImage:"assets/projects/mr-vaibhav-dhokle/exterior-1.jpg",galleryImages:["assets/projects/mr-vaibhav-dhokle/exterior-1.jpg","assets/projects/mr-vaibhav-dhokle/living-room-1.jpg","assets/projects/mr-vaibhav-dhokle/kitchen-1.jpg","assets/projects/mr-vaibhav-dhokle/master-bedroom-1.jpg"],heroVideo:{loop:{src:"assets/projects/mr-vaibhav-dhokle/video/hero-loop.mp4",poster:"assets/projects/mr-vaibhav-dhokle/video/hero-loop.jpg",orientation:"portrait"},film:{src:"assets/projects/mr-vaibhav-dhokle/video/film.mp4",poster:"assets/projects/mr-vaibhav-dhokle/video/film.jpg",orientation:"portrait",durationSeconds:31}},summary:"A contemporary farmhouse in Karandi, where warm minimalism meets natural wood, soft neutrals and controlled colour accents.",description:["Set on a 30,000 sq.ft. plot in Karandi, this 3,000 sq.ft. farmhouse was designed and built over a year and a half, completing in 2025. Contemporary, warm-minimal and quietly luxurious, it carries a consistent vocabulary of vertical lines, framed surfaces and tactile finishes from the fa\xE7ade through every room.","Warm ivory surfaces form the neutral canvas of the interiors, complemented by walnut-toned wood that introduces depth and natural character. Charcoal elements, smoked glass and dark metal detailing provide architectural contrast, while muted aqua cabinetry and deep teal upholstery bring carefully controlled colour into the composition. Externally, a crisp white-and-charcoal envelope is punctuated by a dramatic geometric textured wall at the entrance."],specs:[{label:"Location",value:"Karandi"},{label:"Plot Area",value:"30,000 sq.ft."},{label:"Built-up Area",value:"3,000 sq.ft."},{label:"Completion",value:"2025 (1.5-year build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:"Contemporary warm minimalism"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"Hafele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Kitchen Counters",value:"Kalinga Stone"},{label:"Lighting",value:"Hybec"},{label:"Paint",value:"Asian Paints"}],sections:[{heading:"Exterior",body:["A crisp white-and-charcoal envelope establishes a strong architectural frame, while the geometric entrance wall provides depth, texture and identity.","Dark granite steps and charcoal paving ground the composition, while toughened clear-glass balcony railings in dark bronze frames retain visual lightness."],image:"assets/projects/mr-vaibhav-dhokle/exterior-1.jpg"},{heading:"Living Room",body:["Formal seating in plush champagne-beige velvet, accented with deep teal upholstery and carved antique-silver frames, gathers around a white marble-look centre table on a textured grey, teal and beige rug.","A dark walnut display unit with charcoal open niches and warm-white 3000K lighting completes the room."],image:"assets/projects/mr-vaibhav-dhokle/living-room-1.jpg",gallery:["assets/projects/mr-vaibhav-dhokle/living-room-2.jpg"]},{heading:"Kitchen",body:["Pastel aqua base cabinetry is paired with warm ivory overheads, walnut tall units and open shelves, smoked-black glass shutters and a light quartz worktop, creating a fresh yet sophisticated palette.","Matte black gola profiles and faucet, a brushed-steel sink and under-cabinet LED task lighting complete the composition."],image:"assets/projects/mr-vaibhav-dhokle/kitchen-1.jpg",gallery:["assets/projects/mr-vaibhav-dhokle/kitchen-2.jpg"]},{heading:"Master Bedroom",body:["A soft monochromatic envelope is enriched through vertical fluting and upholstered panels, creating height, rhythm and tactile comfort.","Warm ivory wardrobe shutters with fluted lower panels sit within walnut framing, beside a taupe upholstered bed-back, walnut-and-ivory bedside tables, and layered taupe curtains with off-white sheers."],image:"assets/projects/mr-vaibhav-dhokle/master-bedroom-1.jpg",gallery:["assets/projects/mr-vaibhav-dhokle/master-bedroom-2.jpg"]},{heading:"Bedroom 1",body:[],image:"assets/projects/mr-vaibhav-dhokle/video/bedroom-1-loop.jpg"},{heading:"Bedroom 2",body:[],image:"assets/projects/mr-vaibhav-dhokle/bedroom-2-1.jpg"}],reels:[{title:"Living Room",src:"assets/projects/mr-vaibhav-dhokle/video/living-room-loop.mp4",poster:"assets/projects/mr-vaibhav-dhokle/video/living-room-loop.jpg",durationSeconds:8},{title:"Master Bedroom",src:"assets/projects/mr-vaibhav-dhokle/video/master-bedroom-loop.mp4",poster:"assets/projects/mr-vaibhav-dhokle/video/master-bedroom-loop.jpg",durationSeconds:8},{title:"Bedroom 1",src:"assets/projects/mr-vaibhav-dhokle/video/bedroom-1-loop.mp4",poster:"assets/projects/mr-vaibhav-dhokle/video/bedroom-1-loop.jpg",durationSeconds:7},{title:"Bedroom 2",src:"assets/projects/mr-vaibhav-dhokle/video/bedroom-2-loop.mp4",poster:"assets/projects/mr-vaibhav-dhokle/video/bedroom-2-loop.jpg",durationSeconds:8}],photographer:"@manthanyadav.studio"},{slug:"mr-abhimanyu-gaikwad",title:"Mr. Abhimanyu Gaikwad",categories:["interior"],location:"Kondhanpuri",area:"2,000 sq.ft. plot",year:2020,heroImage:"assets/projects/mr-abhimanyu-gaikwad/exterior-1.jpg",galleryImages:["assets/projects/mr-abhimanyu-gaikwad/exterior-1.jpg","assets/projects/mr-abhimanyu-gaikwad/entrance-1.jpg","assets/projects/mr-abhimanyu-gaikwad/living-room-1.jpg","assets/projects/mr-abhimanyu-gaikwad/kitchen-1.jpg","assets/projects/mr-abhimanyu-gaikwad/bedroom-3-1.jpg"],summary:"Earthbound Elegance: a contemporary residence in Kondhanpuri where walnut wood, olive-green accents and stone-inspired surfaces meet clean, modern detailing.",description:['The design concept, "Earthbound Elegance," explores a harmonious blend of natural textures, warm wood finishes, muted colours, and contemporary detailing to create a sophisticated yet welcoming living environment. The design language balances modern minimalism with earthy elements, allowing each space to express its own character while maintaining a cohesive visual identity throughout the home.',"The material palette is anchored by rich walnut wood laminates, olive-green accents, warm white walls, soft grey surfaces, and stone-inspired flooring. Wooden battens, geometric jali patterns, and textured wall panels introduce depth and visual interest, while fluted glass shutters and sleek cabinetry bring a refined contemporary touch. Bedrooms are designed as tranquil retreats, combining upholstered headboards, layered textiles, and thoughtfully integrated bedside storage."],specs:[{label:"Location",value:"Kondhanpuri"},{label:"Plot Area",value:"2,000 sq.ft."},{label:"Built-up Area",value:""},{label:"Completion",value:"2020 (1.5-year build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:'Contemporary, "Earthbound Elegance"'},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"Hafele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Kitchen Counters",value:"Kalinga Stone"},{label:"Lighting",value:"Hybec"},{label:"Paint",value:"Asian Paints"}],sections:[{heading:"Exterior",tagline:"Modern Geometry, Timeless Elegance",body:["The residence showcases a contemporary architectural language defined by bold geometric forms, clean lines, and a balanced interplay of light and dark surfaces. The composition of projecting balconies, strong vertical elements, and layered rooflines creates a distinctive silhouette while maintaining a sense of visual harmony.","A sophisticated palette of charcoal grey, soft white, and textured terracotta brings depth and character to the fa\xE7ade. The terracotta jali panels introduce a subtle traditional Indian influence, while warm architectural lighting highlights the projecting slabs, entrance canopy, and vertical fa\xE7ade elements after sunset."],image:"assets/projects/mr-abhimanyu-gaikwad/exterior-1.jpg",gallery:["assets/projects/mr-abhimanyu-gaikwad/exterior-2.jpg"]},{heading:"Entrance & Pooja Niche",tagline:"Contemporary Indian Entrance",body:["The entrance foyer is designed as a welcoming transitional space that blends traditional Indian aesthetics with contemporary detailing. Rich wooden finishes establish warmth and elegance, while the geometric CNC-cut wooden door adds an artistic element and creates a striking first impression.","The focal wall features a beautifully integrated pooja niche with a floating wooden ledge for placing sacred idols. Vertical decorative panels with diamond-pattern detailing, enhanced by warm LED strip lighting, add depth, texture and visual rhythm, while the neutral marble flooring balances the richness of the wood."],image:"assets/projects/mr-abhimanyu-gaikwad/entrance-1.jpg"},{heading:"Living Room",tagline:"Warm \xB7 Clean \xB7 Elegant",body:["The living area incorporates warm wooden finishes, subtle textures, and ambient lighting to establish a sense of comfort and understated luxury."],image:"assets/projects/mr-abhimanyu-gaikwad/living-room-1.jpg"},{heading:"Kitchen",tagline:"Sleek \xB7 Modern \xB7 Functional",body:["The kitchen features a sophisticated combination of muted grey cabinetry, dark stone countertops, and fluted glass shutters, creating a balance between functionality and aesthetics."],image:"assets/projects/mr-abhimanyu-gaikwad/kitchen-1.jpg"},{heading:"Bedroom 1",tagline:"Earthy \xB7 Calm \xB7 Minimal",body:[],image:"assets/projects/mr-abhimanyu-gaikwad/bedroom-1-1.jpg",gallery:["assets/projects/mr-abhimanyu-gaikwad/bedroom-1-2.jpg","assets/projects/mr-abhimanyu-gaikwad/bedroom-1-3.jpg"]},{heading:"Bedroom 2",tagline:"Warm \xB7 Textured \xB7 Contemporary",body:[],image:"assets/projects/mr-abhimanyu-gaikwad/bedroom-2-1.jpg",gallery:["assets/projects/mr-abhimanyu-gaikwad/bedroom-2-2.jpg","assets/projects/mr-abhimanyu-gaikwad/bedroom-2-3.jpg"]},{heading:"Bedroom 3",tagline:"Playful \xB7 Fresh \xB7 Nature Inspired",body:[],image:"assets/projects/mr-abhimanyu-gaikwad/bedroom-3-1.jpg",gallery:["assets/projects/mr-abhimanyu-gaikwad/bedroom-3-2.jpg"]}],photographer:"@manthanyadav.studio"},{slug:"mr-dhananjay-gaikwad",title:"Mr. Dhananjay Gaikwad",categories:["interior"],location:"Kondhanpuri",area:"2,000 sq.ft. plot",year:2020,heroImage:"assets/projects/mr-dhananjay-gaikwad/exterior-1.jpg",galleryImages:["assets/projects/mr-dhananjay-gaikwad/exterior-1.jpg","assets/projects/mr-dhananjay-gaikwad/living-room-1.jpg","assets/projects/mr-dhananjay-gaikwad/dining-1.jpg","assets/projects/mr-dhananjay-gaikwad/jali-pooja-1.jpg","assets/projects/mr-dhananjay-gaikwad/bedroom-3-1.jpg"],summary:"A Home in Harmonious Hues: a contemporary farmhouse in Kondhanpuri with a carved walnut ceiling, a terracotta jali screen and warm, softly coloured rooms.",description:["A Home in Harmonious Hues is a contemporary expression of warmth, texture and timeless design. Each space has its own visual identity while maintaining a cohesive aesthetic throughout the home.","Warm walnut-toned laminates bring depth and continuity to the bedrooms, wardrobes, doors, and decorative panelling. The colour story combines warm neutrals with selective accents of sage green, powder blue, teal, and terracotta, while vertical wooden battens, geometric wardrobe patterns, and fluted surfaces introduce rhythm and visual interest. The result is a contemporary home that feels refined yet welcoming, where modern design sensibilities coexist with natural warmth and subtle Indian influences."],specs:[{label:"Location",value:"Kondhanpuri"},{label:"Plot Area",value:"2,000 sq.ft."},{label:"Built-up Area",value:""},{label:"Completion",value:"2020 (1.5-year build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:'Contemporary, "A Home in Harmonious Hues"'},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"Hafele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Kitchen Counters",value:"Kalinga Stone"},{label:"Lighting",value:"Hybec"},{label:"Paint",value:"Asian Paints"}],sections:[{heading:"Exterior",tagline:"Modern Architecture | Form \u2022 Material \u2022 Light",body:["The residence is designed with a contemporary architectural approach that emphasises clean geometry, balanced proportions, and a sophisticated material palette. The composition of intersecting volumes, projecting roof slabs, and well-defined planes creates a visually striking yet elegant fa\xE7ade.","A harmonious combination of textured charcoal-grey surfaces, soft white finishes, and warm wooden accents defines the exterior identity. Strategically positioned recessed lights highlight the architectural volumes, while the landscaped lawn, potted plants, and perimeter greenery soften the building\u2019s geometric character."],image:"assets/projects/mr-dhananjay-gaikwad/exterior-1.jpg",gallery:["assets/projects/mr-dhananjay-gaikwad/exterior-2.jpg"]},{heading:"Living Room",tagline:"Sculpted Wood Ceiling & Statement Aesthetics",body:["The design celebrates the grandeur of traditional craftsmanship through a contemporary interpretation of ornamental woodwork. The ceiling features a rich walnut-toned wooden finish, enhanced by an intricately carved circular medallion that serves as the focal point of the double-height living space.","A cascading crystal chandelier is suspended from the centre of the carved medallion, creating a striking interplay of light, reflection, and texture. The dark charcoal-grey feature wall provides a sophisticated contrast to the warmth of the wood, while the matching carved wooden wall medallion and vertical wooden door detailing reinforce the design language."],image:"assets/projects/mr-dhananjay-gaikwad/living-room-1.jpg",gallery:["assets/projects/mr-dhananjay-gaikwad/living-room-2.jpg","assets/projects/mr-dhananjay-gaikwad/living-room-3.jpg","assets/projects/mr-dhananjay-gaikwad/living-room-4.jpg"]},{heading:"Dining",body:[],image:"assets/projects/mr-dhananjay-gaikwad/dining-1.jpg"},{heading:"Kitchen",tagline:"Modern \xB7 Sleek \xB7 Functional",body:["Matte charcoal and off-white laminates establish a sophisticated foundation in the kitchen, complemented by fluted glass shutters that introduce texture and subtle transparency. Dark stone countertops and light grey wall finishes create a refined contrast, balancing functionality with visual appeal."],image:"assets/projects/mr-dhananjay-gaikwad/kitchen-1.jpg"},{heading:"Jali Screen & Pooja Niche",tagline:"Terracotta Finish \xB7 Natural Light & Shadow Play",body:["The terracotta jali screen is a distinctive architectural feature. Its intricate pattern filters daylight, creates dynamic shadow play, and adds a traditional Indian element to the modern design language. Similarly, the wooden pooja niche celebrates craftsmanship through detailed panelling, warm illumination, and a thoughtfully framed sacred space."],image:"assets/projects/mr-dhananjay-gaikwad/jali-pooja-1.jpg"},{heading:"Bedroom 1",tagline:"Colour Accent \xB7 Wood Detailing \xB7 Serene",body:[],image:"assets/projects/mr-dhananjay-gaikwad/bedroom-1-1.jpg"},{heading:"Bedroom 2",tagline:"Warm Neutrals \xB7 Wood & White \xB7 Cozy",body:[],image:"assets/projects/mr-dhananjay-gaikwad/bedroom-2-1.jpg",gallery:["assets/projects/mr-dhananjay-gaikwad/bedroom-2-2.jpg"]},{heading:"Bedroom 3",tagline:"Pastel Tone \xB7 Wood Slats \xB7 Minimal",body:[],image:"assets/projects/mr-dhananjay-gaikwad/bedroom-3-1.jpg",gallery:["assets/projects/mr-dhananjay-gaikwad/bedroom-3-2.jpg","assets/projects/mr-dhananjay-gaikwad/bedroom-3-3.jpg"]},{heading:"Bathroom",tagline:"Natural Stone \xB7 Warm Wood \xB7 Contemporary",body:["In the bathrooms, stone-textured surfaces create a natural, spa-inspired ambience, while wooden cabinetry and warm metallic accents add richness and sophistication."],image:"assets/projects/mr-dhananjay-gaikwad/bathroom-1.jpg"}],photographer:"@manthanyadav.studio"},{slug:"mr-pande",title:"Mr. Pande",categories:["interior"],location:"Shirur",area:"2,000 sq.ft. plot",year:2020,heroImage:"assets/projects/mr-pande/living-room-1.jpg",galleryImages:["assets/projects/mr-pande/living-room-1.jpg","assets/projects/mr-pande/master-bedroom-1.jpg","assets/projects/mr-pande/secondary-bedroom-1.jpg","assets/projects/mr-pande/third-bedroom-1.jpg"],summary:"A warm contemporary home in Shirur, pairing honey-toned wood and soft ivory with muted dusky-rose accents.",description:["The residence is designed around a warm, contemporary aesthetic that balances functionality, natural textures and understated elegance. A harmonious combination of honey-toned wood, soft ivory finishes, muted dusky-rose accents and neutral upholstery creates a cohesive visual identity throughout the home.","Natural wood textures are paired with matte laminates, stone-inspired surfaces, tactile fabrics and subtle metallic hardware. Warm ambient lighting and decorative pendant fixtures highlight the material contrasts without overwhelming the interiors. Overall, the design achieves a balance between modern sophistication, practical storage and a welcoming residential atmosphere, with a consistent material language connecting the living spaces and bedrooms."],specs:[{label:"Location",value:"Shirur"},{label:"Plot Area",value:"2,000 sq.ft."},{label:"Built-up Area",value:""},{label:"Completion",value:"2020 (6-month build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:"Warm contemporary"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"Hafele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Kitchen Counters",value:"Kalinga Stone"},{label:"Lighting",value:"Hybec"},{label:"Paint",value:"Asian Paints"}],sections:[{heading:"Living Room",body:["The living area features a striking double-height composition with a marble-look TV backdrop, geometrically patterned wooden panelling and a streamlined floating media console. Neutral flooring, understated furniture, glass balustrades and a statement chandelier enhance the sense of openness and sophistication."],image:"assets/projects/mr-pande/living-room-1.jpg",gallery:["assets/projects/mr-pande/living-room-2.jpg","assets/projects/mr-pande/living-room-3.jpg"]},{heading:"Master Bedroom",body:["The bedroom combines a warm wooden feature wall, upholstered headboard, coordinated bedside units and soft neutral bedding. Integrated storage, Roman blinds and carefully positioned decorative lighting create a calm and comfortable retreat."],image:"assets/projects/mr-pande/master-bedroom-1.jpg",gallery:["assets/projects/mr-pande/master-bedroom-2.jpg","assets/projects/mr-pande/master-bedroom-3.jpg"]},{heading:"Secondary Bedroom",body:["A muted dusky-rose and ivory palette introduces a softer, more expressive character. The wardrobe, window-side study or dressing counter, overhead cabinets and storage-integrated bed are designed to maximise functionality while maintaining a cohesive appearance. Geometric headboard detailing and warm wooden accents complete the composition."],image:"assets/projects/mr-pande/secondary-bedroom-1.jpg",gallery:["assets/projects/mr-pande/secondary-bedroom-2.jpg","assets/projects/mr-pande/secondary-bedroom-3.jpg","assets/projects/mr-pande/secondary-bedroom-4.jpg"]},{heading:"Third Bedroom",body:[],image:"assets/projects/mr-pande/third-bedroom-1.jpg",gallery:["assets/projects/mr-pande/third-bedroom-2.jpg","assets/projects/mr-pande/third-bedroom-3.jpg"]}],photographer:"@manthanyadav.studio"},{slug:"mr-vikram-kauthkar",title:"Mr. Vikram Kauthkar",categories:["architecture","interior"],location:"Shirur",area:"3,000 sq.ft. plot",year:2020,heroImage:"assets/projects/mr-vikram-kauthkar/exterior-1.jpg",galleryImages:["assets/projects/mr-vikram-kauthkar/exterior-1.jpg","assets/projects/mr-vikram-kauthkar/entrance-1.jpg","assets/projects/mr-vikram-kauthkar/living-room-1.jpg","assets/projects/mr-vikram-kauthkar/kitchen-1.jpg","assets/projects/mr-vikram-kauthkar/bedroom-1-1.jpg"],summary:"A contemporary Indian residence in Shirur, pairing bold charcoal-and-ivory massing outside with walnut, terracotta and earthy textures within.",description:["This residence explores a harmonious balance between contemporary design, natural textures and warm, earthy tones. The interiors are envisioned as a sophisticated yet welcoming living environment, where thoughtful material selection, custom-designed furniture and carefully composed lighting create a cohesive visual identity.","A palette of warm walnut wood, soft ivory, muted beige and terracotta establishes the foundation of the design. The overall design celebrates the interplay of solid and open surfaces, tactile finishes, geometric detailing and warm ambient illumination. The result is a contemporary Indian home that feels timeless, functional and individually crafted, with every material contributing to the atmosphere and character of the space."],specs:[{label:"Location",value:"Shirur"},{label:"Plot Area",value:"3,000 sq.ft."},{label:"Built-up Area",value:""},{label:"Completion",value:"2020 (1.5-year build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:"Contemporary Indian"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"H\xE4fele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Lighting",value:"Jaquar"},{label:"Kitchen",value:"Kalinga Stone"},{label:"Hardware",value:"H\xE4fele, Hettich, Quba, Bose"},{label:"Paint",value:"Asian Paints"},{label:"Construction Materials",value:"Cement (Birla A1), Steel (Polad)"},{label:"Artifacts",value:"IKEA, White House"}],sections:[{heading:"Exterior",tagline:"Contemporary Elegance in Modern Architecture",body:["This contemporary residence reflects a refined approach to modern Indian living, combining bold geometric forms with a sophisticated palette of charcoal grey, cool grey, and warm ivory. Teak-toned accents introduce natural warmth, while glass railings and slim metal fins add visual lightness to the fa\xE7ade.","Layered lighting highlights the architectural details, creating an inviting ambience against the evening sky. Textured surfaces and projecting slabs enhance depth, while tropical landscaping softens the structure and establishes a connection with nature."],image:"assets/projects/mr-vikram-kauthkar/exterior-1.jpg",gallery:["assets/projects/mr-vikram-kauthkar/exterior-2.jpg","assets/projects/mr-vikram-kauthkar/exterior-3.jpg","assets/projects/mr-vikram-kauthkar/exterior-4.jpg"]},{heading:"Entrance",body:["In the entrance, rich wood finishes, textured wall surfaces and integrated storage establish a refined first impression."],image:"assets/projects/mr-vikram-kauthkar/entrance-1.jpg",gallery:["assets/projects/mr-vikram-kauthkar/entrance-2.jpg"]},{heading:"Living Room",tagline:"Architectural Jaali Partition & Contemporary Living",body:["The living room is defined by a striking terracotta jaali partition that transforms the staircase into an architectural focal point. Its intricate geometric pattern introduces traditional Indian craftsmanship within a contemporary design language, creating a balance between openness, privacy and visual interest.","Warm walnut-finished display niches, neutral upholstered seating and sculptural marble-top coffee tables complement the earthy terracotta tones. Soft ambient lighting, indoor greenery and a muted ivory palette enhance the warmth and sophistication of the space, creating an inviting living environment with a distinctive architectural identity."],image:"assets/projects/mr-vikram-kauthkar/living-room-1.jpg",gallery:["assets/projects/mr-vikram-kauthkar/living-room-2.jpg","assets/projects/mr-vikram-kauthkar/living-room-3.jpg","assets/projects/mr-vikram-kauthkar/living-room-4.jpg"]},{heading:"Kitchen",body:["The kitchen continues the understated material language through muted sage-green cabinetry, polished black granite countertops and glossy ivory wall tiles."],image:"assets/projects/mr-vikram-kauthkar/kitchen-1.jpg",gallery:["assets/projects/mr-vikram-kauthkar/kitchen-2.jpg"]},{heading:"Bedroom 1",body:[],image:"assets/projects/mr-vikram-kauthkar/bedroom-1-1.jpg",gallery:["assets/projects/mr-vikram-kauthkar/bedroom-1-2.jpg"]},{heading:"Bedroom 2",body:[],image:"assets/projects/mr-vikram-kauthkar/bedroom-2-1.jpg"}],photographer:"@manthanyadav.studio"},{slug:"nakshatra",title:"Nakshatra",categories:["architecture","interior"],location:"Shirur",area:"2,500 sq.ft. built-up",year:2024,heroImage:"assets/projects/nakshatra/exterior-1.jpg",galleryImages:["assets/projects/nakshatra/exterior-1.jpg","assets/projects/nakshatra/exterior-2.jpg","assets/projects/nakshatra/living-room-1.jpg","assets/projects/nakshatra/bedroom-1-1.jpg","assets/projects/nakshatra/bedroom-2-1.jpg"],summary:"A warm contemporary bungalow in Shirur, with a stone-and-timber fa\xE7ade and interiors layered in walnut, soft neutrals and crafted detail.",description:["A warm contemporary material palette that combines rich wood finishes with soft neutral tones and natural textures. Walnut wood adds warmth and depth, while beige upholstery and off-white walls create a calm, elegant base. Charcoal fluted panels bring a modern architectural element, complemented by marble-finish flooring, textured glass, decorative jaali and natural cane details.","Natural cane, decorative jaali elements and warm ambient lighting add layers of craftsmanship and character, creating a cohesive residential environment that feels elegant, comfortable and inviting."],specs:[{label:"Location",value:"Shirur"},{label:"Plot Area",value:"25,000 sq.ft."},{label:"Built-up Area",value:"2,500 sq.ft."},{label:"Completion",value:"2024 (1.5-year build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:"Warm contemporary"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"H\xE4fele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Lighting",value:"Jaquar"},{label:"Kitchen",value:"Kalinga Stone"},{label:"Hardware",value:"H\xE4fele, Hettich, Chetna, Quba, Bose"},{label:"Paint",value:"Asian Paints"},{label:"Construction Materials",value:"Cement (Birla A1), Steel (Polad)"}],sections:[{heading:"Exterior",body:["A modern and luxurious home exterior, bathed in warm evening light that highlights its intricate details. The fa\xE7ade is a stunning blend of stone and wood, creating a rich and textural contrast.","The warm glow emanating from the roofline and the strategically placed spotlights adds an air of sophistication and elegance, while the lush greenery softens the angular lines of the structure, creating a harmonious balance between nature and architecture."],image:"assets/projects/nakshatra/exterior-1.jpg",gallery:["assets/projects/nakshatra/exterior-2.jpg"]},{heading:"Living Room",body:[],image:"assets/projects/nakshatra/living-room-1.jpg"},{heading:"Pooja",body:[],image:"assets/projects/nakshatra/pooja-1.jpg"},{heading:"Bedroom 1",body:["A sleek and minimalist bedroom with a focus on clean lines and high-quality materials. The statement headboard, featuring a geometric pattern with gold accents, adds a touch of sophistication and luxury, while the built-in white cabinets offer ample storage and keep the room airy and spacious.","The bed, with its grey quilted bedspread and stylish throw, adds a layer of texture and comfort, and plants and natural light bring a sense of peace and tranquility to the space."],image:"assets/projects/nakshatra/bedroom-1-1.jpg",gallery:["assets/projects/nakshatra/bedroom-1-2.jpg"]},{heading:"Bedroom 2",body:["This contemporary bedroom boasts a sleek and stylish design with a focus on clean lines and minimalist decor. The focal point of the room is the grey wall panelling with vertical lines, adding a touch of sophistication and texture.","The white ceiling with recessed lighting creates a bright and airy ambiance, and the patterned throw adds a cozy and inviting feel, while the plants bring a touch of nature indoors."],image:"assets/projects/nakshatra/bedroom-2-1.jpg",gallery:["assets/projects/nakshatra/bedroom-2-2.jpg"]}],photographer:"@manthanyadav.studio"},{slug:"the-flamingo",title:"The Flamingo",categories:["interior"],location:"Shirur",area:"2,000 sq.ft.",year:2026,heroImage:"assets/projects/the-flamingo/living-room-1.jpg",galleryImages:["assets/projects/the-flamingo/living-room-1.jpg","assets/projects/the-flamingo/kitchen-1.jpg","assets/projects/the-flamingo/master-bedroom-1.jpg","assets/projects/the-flamingo/bedroom-1-1.jpg","assets/projects/the-flamingo/bedroom-2-1.jpg"],summary:"A warm contemporary residence in Shirur, where a recurring arch, rich timber and layered neutrals meet a playful flamingo centrepiece.",description:["Designed as a refined contemporary residence, the project explores the relationship between architectural form, tactile materials and everyday comfort. The central idea was to create visual continuity throughout the residence while allowing each space to retain its own identity. Arched profiles, repeated moulding details and warm natural materials become the connecting elements, creating a cohesive design language across the living areas, bedrooms and kitchen.","The interiors follow a philosophy of soft contemporary minimalism: clean enough to feel timeless, but layered enough to feel warm and personal. Walls in warm ivory let the architectural detailing remain subtle, while natural and dark timber introduces contrast and depth, and beige and taupe upholstery soften the stronger architectural elements. Rather than relying heavily on ornamentation, the design uses materiality, proportion and detailing as the primary decorative tools."],specs:[{label:"Location",value:"Shirur"},{label:"Plot Area",value:""},{label:"Built-up Area",value:"2,000 sq.ft."},{label:"Completion",value:"2026 (6-month build)"},{label:"Principal Architect",value:"ID. Pooja Akash Chaudhari, Ar. Akash Chaudhari"},{label:"Design Style",value:"Warm contemporary"},{label:"Flooring",value:"Italian Marble, Ceratec"},{label:"Wall Cladding",value:"POP Gyproc"},{label:"Doors & Partitions",value:"Plywood (Supernova), Veneer (Truewood)"},{label:"Furniture Fittings",value:"H\xE4fele"},{label:"Sanitary Ware",value:"Grohe, American Standard"},{label:"Windows",value:"Saint-Gobain"},{label:"Lighting",value:"Jaquar"},{label:"Kitchen",value:"Kalinga Stone"},{label:"Hardware",value:"H\xE4fele, Hettich, Quba, Bose"},{label:"Paint",value:"Birla Opus"},{label:"Construction Materials",value:"Cement (Birla A1), Steel (Polad)"},{label:"Artifacts",value:"IKEA, White House"}],sections:[{heading:"Living Room",tagline:"Sculptural Warmth",body:["The living room is conceived as a calm, open gathering space with a strong emphasis on proportion and natural light. A warm timber feature wall establishes the visual anchor, while the soft neutral sectional creates a relaxed seating environment. The sculptural coffee tables and statement lighting introduce contemporary forms, while artwork and accessories add a curated layer to the otherwise restrained palette.","The highlight of the room is the arched striped feature installation, where bold black-and-white vertical lines are paired with playful flamingo sculptures. This creates an unexpected moment of colour and character within the sophisticated neutral setting."],image:"assets/projects/the-flamingo/living-room-1.jpg",gallery:["assets/projects/the-flamingo/living-room-2.jpg","assets/projects/the-flamingo/living-room-3.jpg"]},{heading:"Kitchen",tagline:"Functional Elegance",body:["The kitchen takes a more practical interpretation of the home's design language. Muted blue-grey cabinetry is paired with a naturally patterned stone countertop and backsplash, creating a subtle contrast between cool cabinetry and warm stone.","Open shelving, woven baskets and dark glass elements add texture while maintaining a clean and functional composition. The design prioritises storage efficiency, easy maintenance and visual continuity with the rest of the home."],image:"assets/projects/the-flamingo/kitchen-1.jpg"},{heading:"Master Bedroom",tagline:"Soft Architectural Luxury",body:["The master bedroom continues the warm contemporary language through rich timber, upholstered surfaces and curved architectural detailing. The softly upholstered bed creates a comfortable focal point, while the large arched wall treatment adds architectural depth without overwhelming the room.","Integrated wardrobes combine timber frames with textured fabric and cane-like inserts, balancing functionality with visual softness. The overall palette remains muted and tactile, creating a bedroom that feels calm, intimate and timeless."],image:"assets/projects/the-flamingo/master-bedroom-1.jpg"},{heading:"Bedroom 1",tagline:"Contemporary Comfort",body:["The secondary bedroom introduces a lighter palette with dusty blue, warm beige and textured taupe upholstery. The vertically channeled headboard and upholstered bed frame create a sense of continuity, while soft curtains filter natural daylight into the room.","Rounded furniture and carefully selected lighting soften the otherwise structured composition. The result is a youthful yet sophisticated bedroom with a distinctly relaxed character."],image:"assets/projects/the-flamingo/bedroom-1-1.jpg"},{heading:"Bedroom 2",body:[],image:"assets/projects/the-flamingo/bedroom-2-1.jpg",gallery:["assets/projects/the-flamingo/bedroom-2-2.jpg"]}],reels:[{title:"Kitchen",src:"assets/projects/the-flamingo/video/kitchen-loop.mp4",poster:"assets/projects/the-flamingo/video/kitchen-loop.jpg",durationSeconds:8},{title:"Master Bedroom",src:"assets/projects/the-flamingo/video/master-bedroom-loop.mp4",poster:"assets/projects/the-flamingo/video/master-bedroom-loop.jpg",durationSeconds:8},{title:"Bedroom 1",src:"assets/projects/the-flamingo/video/bedroom-1-loop.mp4",poster:"assets/projects/the-flamingo/video/bedroom-1-loop.jpg",durationSeconds:7},{title:"Bedroom 2",src:"assets/projects/the-flamingo/video/bedroom-2-loop.mp4",poster:"assets/projects/the-flamingo/video/bedroom-2-loop.jpg",durationSeconds:7}],photographer:"@manthanyadav.studio"}];function k(e){return d.find(l=>l.slug===e)}function A(e){return e==="all"?d:d.filter(l=>l.categories.includes(e))}var S=[{value:"architecture",label:"Architecture"},{value:"interior",label:"Interior"},{value:"landscape",label:"Landscape"}];export{j as a,d as b,k as c,A as d,S as e};
